mapper.select:
SELECT ROW_NUMBER() OVER (ORDER BY a.AGENCYCD, a.DOWNLOADDT DESC) AS no , a.filenm AS fileNm , a.fileUrl AS fileUrl , a.DOWNLOADDT AS downloadDt , a.AGENCYCD AS agencyCd , b.AGENCYNM AS agencyNm , a.UPLOADYN AS uploadYn , CASE WHEN a.UPLOADYN = 1 THEN 'O' ELSE 'X' END AS uploadYnNm , a.FILESTATUS AS fileStatus , CASE WHEN a.FILESTATUS = 1 THEN '정상파일' WHEN a.FILESTATUS = 2 THEN '파일내용없음' WHEN a.FILESTATUS = 3 THEN '파일깨짐' WHEN a.FILESTATUS = 4 THEN '업로드대기중' ELSE '에러확인필요' END AS fileStatusNm , a.INSERTDT AS insertDt , a.UPLOADDT AS uploadDt FROM ysc.tc_milkbang_file a LEFT JOIN ysc.tc_agency b ON a.AGENCYCD = b.AGENCYCD WHERE 1 = 1 AND to_char(a.DOWNLOADDT, 'yyyymmdd') BETWEEN replace(#{startDate}, '-', '') AND replace(#{endDate}, '-', '')
AND a.AGENCYCD = #{agencyCd}
ORDER BY a.AGENCYCD, a.DOWNLOADDT DESC

SELECT ROW_NUMBER() OVER (ORDER BY a.AGENCYNM) AS no , a.AGENCYCD AS agencyCd , a.AGENCYNM AS agencyNm , a.AGENCYTYPE AS agencyType , a.TEAMPERSONCD AS teamPersonCd , c.TEAMPERSONNM AS teamPersonNm , a.DELETEYN AS deleteYn , '전송안됨' AS uploadYnNm , count(*) AS cnt FROM ysc.tc_agency a LEFT JOIN ysc.tc_milkbang_file b ON to_char(a.AGENCYCD) = to_char(b.AGENCYCD) AND to_char(b.DOWNLOADDT, 'yyyymmdd') BETWEEN REPLACE(#{startDate}, '-', '') AND REPLACE(#{endDate}, '-', '') LEFT JOIN ysc.TC_TEAMPERSON c ON a.TEAMPERSONCD = c.TEAMPERSONCD WHERE 1 = 1 AND b.AGENCYCD IS NULL AND a.DELETEYN = '0'
AND a.TEAMPERSONCD = #{teamPersonCd}
GROUP BY a.AGENCYCD, a.AGENCYNM, a.AGENCYTYPE, a.TEAMPERSONCD, c.TEAMPERSONNM, a.DELETEYN ORDER BY a.AGENCYNM

mapper.insert:
INSERT INTO ysc.tc_milkbang_file (
    FILENM
    , FILEURL
    , DOWNLOADDT
    , AGENCYCD
    , UPLOADYN
    , UPLOADDT
    , FILESTATUS
    , INSERTDT
) VALUES (
    #{fileNm}
    , #{fileUrl}
    , SYSDATE
    , #{agencyCd}
    , #{uploadYn}
    , null
    , #{fileStatus}
    , null
)

mapper.update:
UPDATE ysc.tc_milkbang_file
SET
    DOWNLOADDT = SYSDATE
    , AGENCYCD = #{agencyCd}
    , UPLOADYN = #{uploadYn}
    , FILESTATUS = #{fileStatus}
WHERE FILENM = #{fileNm}
